create table public.comun_pauta_modules(id uuid primary key default gen_random_uuid(),pauta_id uuid not null references public.comun_pauta_spaces(id) on delete cascade,module_type text not null check(module_type in('overview','construction_circle','reports','evidence','map','observatory','metrics','documents','timeline','proposals','actions','tasks','calendar','results','archive','art_gallery_future','community_radio_future','participation')),title_override text,public_description text,position integer not null default 0 check(position>=0),status text not null default 'draft' check(status in('draft','active','paused','archived')),visibility text not null default 'private' check(visibility in('public','participants','internal','private')),config jsonb not null default '{}' check(jsonb_typeof(config)='object' and pg_column_size(config)<=16384),created_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(pauta_id,module_type));
create table public.comun_construction_circles(id uuid primary key default gen_random_uuid(),pauta_id uuid not null references public.comun_pauta_spaces(id) on delete cascade,module_id uuid references public.comun_pauta_modules(id) on delete set null,title text not null,public_question text not null,public_context text,status text not null default 'draft' check(status in('draft','open','synthesizing','decision','action','completed','paused','archived')),participation_mode text not null default 'moderated_public' check(participation_mode in('moderated_public','registered_members','invited_group','internal')),current_round_id uuid,starts_at timestamptz,closes_at timestamptz,created_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_construction_circle_rounds(id uuid primary key default gen_random_uuid(),circle_id uuid not null references public.comun_construction_circles(id) on delete cascade,round_type text not null check(round_type in('listening','evidence_gathering','diagnosis','proposals','prioritization','decision','action_planning','evaluation','memory')),title text not null,public_prompt text not null,public_guidance text,position integer not null check(position>=0),status text not null default 'planned' check(status in('planned','open','closed','synthesized','archived')),opens_at timestamptz,closes_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(circle_id,position));
alter table public.comun_construction_circles add constraint comun_circles_current_round_fk foreign key(current_round_id) references public.comun_construction_circle_rounds(id) on delete set null;
create table public.comun_circle_contributions(id uuid primary key default gen_random_uuid(),circle_id uuid not null references public.comun_construction_circles(id) on delete cascade,round_id uuid not null references public.comun_construction_circle_rounds(id) on delete cascade,contribution_type text not null check(contribution_type in('testimony','question','evidence','correction','proposal','counterpoint','task_offer','support_offer','update','memory')),public_body text not null check(char_length(public_body) between 3 and 6000),private_contact text,author_display_name text,author_member_id uuid,anonymous_publication boolean not null default false,related_evidence_id uuid references public.comun_pauta_evidence_items(id) on delete set null,related_proposal_id uuid,status text not null default 'pending' check(status in('pending','visible','restricted','rejected','incorporated','archived')),moderation_note_private text,public_protocol text unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_circle_syntheses(id uuid primary key default gen_random_uuid(),circle_id uuid not null references public.comun_construction_circles(id) on delete cascade,round_id uuid not null references public.comun_construction_circle_rounds(id) on delete cascade,public_summary text not null,agreements text[] not null default '{}',disagreements text[] not null default '{}',open_questions text[] not null default '{}',missing_evidence text[] not null default '{}',proposed_next_steps text[] not null default '{}',status text not null default 'draft' check(status in('draft','review','published','superseded','archived')),reviewed_by text,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_circle_synthesis_links(id uuid primary key default gen_random_uuid(),synthesis_id uuid not null references public.comun_circle_syntheses(id) on delete cascade,target_type text not null check(target_type in('action','task','proposal','evidence','official_protocol','update')),target_id uuid,target_label text not null,public_note text,confirmed_by text,confirmed_at timestamptz,created_at timestamptz not null default now());
create table public.comun_pauta_updates(id uuid primary key default gen_random_uuid(),pauta_id uuid not null references public.comun_pauta_spaces(id) on delete cascade,circle_id uuid references public.comun_construction_circles(id) on delete set null,title text not null,body text not null,update_type text not null default 'process' check(update_type in('process','decision','action','result','correction')),visibility text not null default 'public' check(visibility in('public','participants','internal')),status text not null default 'draft' check(status in('draft','published','archived')),published_at timestamptz,created_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_member_profiles(user_id uuid primary key,display_name text not null,public_slug text unique,public_bio text,territory_id uuid references public.comun_hub_territories(id) on delete set null,participation_visibility text not null default 'private' check(participation_visibility in('public','participants','private')),status text not null default 'active' check(status in('active','paused','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.comun_pauta_memberships(id uuid primary key default gen_random_uuid(),pauta_id uuid not null references public.comun_pauta_spaces(id) on delete cascade,member_user_id uuid not null,role text not null default 'participant' check(role in('participant','facilitator','curator','field_observer','researcher','communication','coordinator')),status text not null default 'active' check(status in('active','paused','left','archived')),joined_at timestamptz not null default now(),left_at timestamptz,unique(pauta_id,member_user_id));
create index comun_pauta_modules_public on public.comun_pauta_modules(pauta_id,position) where status='active' and visibility='public';create index comun_circle_rounds_open on public.comun_construction_circle_rounds(circle_id,status,position);create index comun_circle_contributions_public on public.comun_circle_contributions(round_id,contribution_type) where status in('visible','incorporated');create index comun_pauta_updates_public on public.comun_pauta_updates(pauta_id,published_at desc) where status='published' and visibility='public';
do $$ declare t text; begin foreach t in array array['comun_pauta_modules','comun_construction_circles','comun_construction_circle_rounds','comun_circle_contributions','comun_circle_syntheses','comun_circle_synthesis_links','comun_pauta_updates','comun_member_profiles','comun_pauta_memberships'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon, authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;end $$;
